package cn.adc.duration;
import cn.adc.shared.audit.*;import cn.adc.shared.config.ConfigurationUnavailable;import cn.adc.shared.db.JdbcTransactions;import jakarta.servlet.http.HttpServletRequest;import tools.jackson.databind.*;import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
@RestController @ConditionalOnBean(DurationAccess.class) @RequestMapping("/api/v1")
public final class DurationController {
 private final DurationAccess access;public DurationController(DurationAccess access){this.access=access;}
 private DurationOperations service(HttpServletRequest r){if(access.identity(r).current().isEmpty())throw new SecurityException("AUTHENTICATION_REQUIRED");return access.service(r);}
 private void writeIdentity(HttpServletRequest r,String csrf){service(r);access.identity(r).requireCsrf(csrf);}
 public static Map<String,Object> dto(JsonNode n){var m=new LinkedHashMap<String,Object>();m.put("projectId",n.path("project_id").asText());m.put("versionNo",n.path("duration_version_no").intValue());m.put("projectName",n.path("project_name").asText());m.put("durationMinutes",n.path("duration_minutes").intValue());m.put("publicationStatus",n.path("publication_status").asText());for(String[] pair:List.of(new String[]{"publishedAt","published_at"},new String[]{"publishedBy","published_by"})){var v=n.get(pair[1]);m.put(pair[0],v==null||v.isNull()?null:v.asText());}var evidence=n.get("publication_evidence");m.put("publicationEvidence",evidence==null||evidence.isNull()?null:evidence);m.put("stateToken",AuditDocuments.hash(n));return m;}
 private ResponseEntity<Map<String,Object>> receipt(CommandRecovery.Receipt r,String op,boolean invalid){var body=new LinkedHashMap<String,Object>();body.put("requestReference",r.requestReference());body.put("status",r.businessOutcome().equals("SUCCEEDED")?"COMMITTED":r.businessOutcome());body.put("operationCode",op);body.put("auditPersistence",r.auditPersistence().name());body.put("message",r.businessOutcome().equals("SUCCEEDED")?"配置操作已提交":"请按操作及审计状态核对结果");body.put("existingResult",r.existingResult());if(r.result()!=null){var n=r.result().path("targetVersion");if(n.isObject())body.put("versionRef",Map.of("projectId",n.path("project_id").asText(),"versionNo",n.path("duration_version_no").intValue()));}int status=switch(r.businessOutcome()){case "SUCCEEDED"->200;case "UNKNOWN"->202;case "FAILED"->503;default->invalid?400:409;};return ResponseEntity.status(status).cacheControl(CacheControl.noStore()).body(body);}
 @GetMapping("/staff/duration-projects") public ResponseEntity<?> list(HttpServletRequest r,@RequestParam(defaultValue="50")int limit,@RequestParam(defaultValue="0")long after){var s=service(r);var page=s.currentPage(limit,after);var out=new LinkedHashMap<String,Object>();out.put("items",page.stream().limit(limit).map(DurationController::dto).toList());out.put("nextCursor",page.size()>limit?page.get(limit-1).path("project_id").asText():null);out.put("capabilities",s.capabilities());out.put("csrfToken",access.identity(r).csrfToken());out.put("requestNamespace",s.requestNamespace());return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(out);}
 @GetMapping("/staff/duration-projects/{projectId}/versions/{versionNo}") public ResponseEntity<?> version(HttpServletRequest r,@PathVariable long projectId,@PathVariable int versionNo){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(dto(service(r).version(projectId,versionNo)));}
 @PostMapping("/headquarters/duration-project-drafts") public ResponseEntity<?> create(HttpServletRequest r,@RequestHeader("Idempotency-Key") String key,@RequestHeader(value="X-CSRF-Token",required=false)String csrf,@RequestBody JsonNode body){writeIdentity(r,csrf);boolean invalid=false;try{DurationPolicyService.validateDraft(body);}catch(IllegalArgumentException e){invalid=true;}return receipt(service(r).create(UUID.fromString(key),body),"DURATION_DRAFT_CREATE",invalid);}
 @PutMapping("/headquarters/duration-projects/{projectId}/versions/{versionNo}/draft") public ResponseEntity<?> edit(HttpServletRequest r,@PathVariable long projectId,@PathVariable int versionNo,@RequestHeader("Idempotency-Key") String key,@RequestHeader(value="X-CSRF-Token",required=false)String csrf,@RequestBody JsonNode body){writeIdentity(r,csrf);boolean invalid=false;try{DurationPolicyService.validateDraft(body);}catch(IllegalArgumentException e){invalid=true;}return receipt(service(r).edit(UUID.fromString(key),projectId,versionNo,body),"DURATION_DRAFT_EDIT",invalid);}
 @PostMapping("/headquarters/duration-projects/{projectId}/versions/{versionNo}/publications") public ResponseEntity<?> publish(HttpServletRequest r,@PathVariable long projectId,@PathVariable int versionNo,@RequestHeader("Idempotency-Key") String key,@RequestHeader(value="X-CSRF-Token",required=false)String csrf,@RequestBody JsonNode body){writeIdentity(r,csrf);return receipt(service(r).publish(UUID.fromString(key),projectId,versionNo,body),"DURATION_PUBLISH",false);}
 @GetMapping("/headquarters/duration-commands/{*requestReference}") public ResponseEntity<?> recover(HttpServletRequest r,@PathVariable String requestReference){String ref=requestReference.startsWith("/")?requestReference.substring(1):requestReference;String[] parts=ref.split("/");var response=service(r).recover(ref);return receipt(response,parts.length==5?parts[3]:"DURATION_PUBLISH",false);}
 @ExceptionHandler(SecurityException.class) ResponseEntity<?> denied(SecurityException e){return error(e.getMessage().equals("AUTHENTICATION_REQUIRED")?401:403);}
 @ExceptionHandler({IllegalArgumentException.class}) ResponseEntity<?> badInput(IllegalArgumentException e){return error("VERSION_NOT_FOUND".equals(e.getMessage())?404:400);}
 @ExceptionHandler({JdbcTransactions.Failure.class,ConfigurationUnavailable.class}) ResponseEntity<?> unavailable(){return error(503);}
 private ResponseEntity<?> error(int status){return ResponseEntity.status(status).cacheControl(CacheControl.noStore()).body(Map.of("code","HTTP_"+status,"message","配置操作无法完成"));}
}
